begin;
do $$
declare clerk uuid:=gen_random_uuid();other_user uuid:=gen_random_uuid();admin uuid:=gen_random_uuid();student uuid:=gen_random_uuid(); sr uuid; sid bigint;outside bigint;lesson uuid;other_lesson uuid;r jsonb;v bigint;n int;payload jsonb;
begin
 insert into public.submission_cohorts(name) values('10月班'),('11月班') on conflict do nothing;
 insert into auth.users(id,email,email_confirmed_at) values(clerk,'att-clerk@example.invalid',now()),(other_user,'att-other@example.invalid',now()),(admin,'att-admin@example.invalid',now()),(student,'att-student@example.invalid',now());
 insert into public.user_roles(user_id,role) values(admin,'super_admin'),(student,'student');
 insert into public.submissions(type,name,cohort,data,school_form) values('application','名单甲','10月班','{"phone":"private phone"}','{"health":"private form"}') returning id into sid;
 insert into public.submissions(type,name,cohort,data) values('application','其他班秘密','11月班','{}') returning id into outside;
 insert into public.submissions(type,name,cohort,student_user_id) values('application','考勤学生','10月班',student);
 perform set_config('amas.rpc_context','student',true);
 insert into public.student_records(user_id,student_number) values(student,'B26-ATT') returning id into sr;
 perform public.activate_student(sr,admin,'正式注册','synthetic attendance fixture');
 insert into public.cohort_sessions(cohort,held_on,title,note) values('11月班','2026-10-19','其他班课次','staff private note') returning id into other_lesson;
 perform set_config('amas.test.uid',admin::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',admin,'aal','aal2')::text,true);
 execute 'set role authenticated';
 r:=public.admin_set_attendance_operator(clerk,true);if r->>'ok'<>'true' then raise exception 'A01 assignment failed %',r;end if;
 if public.admin_set_attendance_operator(student,true)->>'ok'<>'true' then raise exception 'A02 existing October student cannot be assigned';end if;
 execute 'reset role';
 if (select status from public.student_records where id=sr)<>'active' or not public.has_active_role(student,'student') then raise exception 'A02 academic identity changed';end if;
 perform set_config('amas.test.uid',student::text,true);
 execute 'set role authenticated';
 if exists(select 1 from public.my_roles() where role='student') or not exists(select 1 from public.my_roles() where role='attendance_clerk') then raise exception 'A02 workspace is not attendance-only';end if;
 perform public.attendance_day('2026-10-19');
 execute 'reset role';
 perform set_config('amas.test.uid',admin::text,true);
 execute 'set role authenticated';
 perform public.admin_set_attendance_operator(student,false);
 execute 'reset role';
 perform set_config('amas.test.uid',student::text,true);
 execute 'set role authenticated';
 if not exists(select 1 from public.my_roles() where role='student') then raise exception 'A02 revocation did not restore original workspace';end if;
 execute 'reset role';
 perform set_config('amas.test.uid',admin::text,true);
 execute 'set role authenticated';
 execute 'reset role';
 perform set_config('amas.test.uid',clerk::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',clerk,'aal','aal2')::text,true);
 execute 'set role authenticated';
 if not exists(select 1 from public.my_roles() where role='attendance_clerk') or exists(select 1 from public.my_roles() where role in('registrar','student','super_admin')) then raise exception 'A03 wrong roles';end if;
 select count(*) into n from public.submissions;if n<>0 then raise exception 'A04 raw submissions leaked';end if;
 select count(*) into n from public.cohort_sessions;if n<>0 then raise exception 'A04 raw sessions leaked';end if;
 select count(*) into n from public.cohort_marks;if n<>0 then raise exception 'A04 raw marks leaked';end if;
 select count(*) into n from public.finance_entries;if n<>0 then raise exception 'A04 finance leaked';end if;
 begin perform public.finance_totals();raise exception 'A04 finance RPC allowed';exception when insufficient_privilege then null;end;
 begin perform public.content_cohorts();raise exception 'A04 content RPC allowed';exception when insufficient_privilege then null;end;
 begin perform public.admin_set_attendance_operator(other_user,true);raise exception 'A04 self grants allowed';exception when insufficient_privilege then null;end;
 r:=public.attendance_day('2026-10-19');
 if r::text like '%private%' or r::text like '%其他班%' or r->>'cohort'<>'10月班' or not exists(select 1 from jsonb_array_elements(r->'roster') p where (p->>'id')::bigint=sid) then raise exception 'A05 projection/scope broken %',r;end if;
 payload:=jsonb_build_array(jsonb_build_object('id',sid,'status','excused','note','已提前请假'));
 r:=public.attendance_save('2026-10-19',null,0,'第1课',payload);
 if r->>'ok'<>'true' then raise exception 'A06 save failed %',r;end if;
 lesson:=(r->>'session')::uuid;v:=(r->>'version')::bigint;
 if public.attendance_save('2026-10-19',null,0,'重试',payload)->>'error'<>'reload_required' then raise exception 'A07 duplicate daily session created';end if;
 if public.attendance_save('2026-10-19',lesson,0,'',payload)->>'error'<>'conflict' then raise exception 'A08 stale version overwrote';end if;
 if public.attendance_save('2026-10-19',other_lesson,0,'',payload)->>'error'<>'outside_cohort' then raise exception 'A09 foreign session allowed';end if;
 if public.attendance_save('2026-10-19',lesson,v,'',jsonb_build_array(jsonb_build_object('id',sid,'status','present'),jsonb_build_object('id',outside,'status','absent')))->>'error'<>'outside_roster' then raise exception 'A10 foreign student batch allowed';end if;
 execute 'reset role';
 if (select attendance from public.cohort_marks where session_id=lesson and submission_id=sid)<>'excused' then raise exception 'A10 invalid batch partially applied';end if;
 update public.cohort_marks set homework='excellent',note='private homework' where session_id=lesson and submission_id=sid;
 select attendance_version into v from public.cohort_sessions where id=lesson;
 execute 'set role authenticated';
 r:=public.attendance_day('2026-10-19');if r::text like '%private homework%' or r::text like '%excellent%' then raise exception 'A11 homework leaked';end if;
 r:=public.attendance_save('2026-10-19',lesson,v,'attempt metadata change',jsonb_build_array(jsonb_build_object('id',sid,'status','late','note','迟到10分钟')));
 if r->>'ok'<>'true' then raise exception 'A12 update failed %',r;end if;
 begin insert into public.cohort_marks(session_id,submission_id,attendance) values(other_lesson,sid,'present');raise exception 'A13 direct write allowed';exception when insufficient_privilege then null;end;
 begin perform public.admin_attendance_operators();raise exception 'A20 clerk lists accounts';exception when insufficient_privilege then null;end;
 if public.attendance_save('2026-10-19',lesson,v,'',jsonb_build_array(jsonb_build_object('id',sid,'status','present'),jsonb_build_object('id',sid,'status','absent')))->>'error'<>'validation_failed' then raise exception 'A21 duplicate student accepted';end if;
 if public.attendance_save('2026-10-19',lesson,v,'','null'::jsonb)->>'error'<>'validation_failed' then raise exception 'A22 null payload accepted';end if;
 execute 'reset role';
 if (select homework from public.cohort_marks where session_id=lesson and submission_id=sid)<>'excellent' or (select note from public.cohort_marks where session_id=lesson and submission_id=sid)<>'private homework' or (select title from public.cohort_sessions where id=lesson)<>'第1课' then raise exception 'A12 unrelated fields modified';end if;
 if (select count(*) from public.audit_logs where actor_id=clerk and event_type='attendance.saved')<>2 then raise exception 'A14 audit missing/duplicate';end if;
 begin insert into public.user_roles(user_id,role) values(clerk,'finance');raise exception 'A15 broad role granted to exclusive account';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',clerk,'aal','aal1')::text,true);
 execute 'set role authenticated';
 begin perform public.attendance_day('2026-10-19');raise exception 'A16 MFA bypass';exception when insufficient_privilege then null;end;
 execute 'reset role';update public.portal_settings set value='false'::jsonb where key='mfa_required';
 execute 'set role authenticated';perform public.attendance_day('2026-10-19');execute 'reset role';
 perform set_config('amas.test.uid',admin::text,true);
 update public.profiles set account_status='disabled' where id=clerk;
 if (select account_status from public.profiles where id=clerk)<>'disabled' then raise exception 'fixture account not disabled';end if;
 perform set_config('amas.test.uid',clerk::text,true);
 execute 'set role authenticated';begin perform public.attendance_day('2026-10-19');raise exception 'A23 disabled account allowed';exception when insufficient_privilege then null;end;execute 'reset role';
 perform set_config('amas.test.uid',admin::text,true);
 update public.profiles set account_status='active' where id=clerk;
 perform set_config('amas.test.uid',clerk::text,true);
 execute 'set role anon';begin perform public.attendance_day('2026-10-19');raise exception 'A24 anonymous allowed';exception when insufficient_privilege then null;end;execute 'reset role';
 update amas_private.attendance_operators set expires_at=now()-interval '1 second' where user_id=clerk;
 execute 'set role authenticated';begin perform public.attendance_day('2026-10-19');raise exception 'A17 expired assignment allowed';exception when insufficient_privilege then null;end;execute 'reset role';
 update amas_private.attendance_operators set expires_at=null,revoked_at=now() where user_id=clerk;
 execute 'set role authenticated';begin perform public.attendance_day('2026-10-19');raise exception 'A18 revoked assignment allowed';exception when insufficient_privilege then null;end;execute 'reset role';
 perform set_config('amas.test.uid',other_user::text,true);
 execute 'set role authenticated';begin perform public.attendance_day('2026-10-19');raise exception 'A19 unassigned user allowed';exception when insufficient_privilege then null;end;execute 'reset role';
 raise notice 'PASS A01-A24 dedicated account, scope, privacy, atomicity, retry, conflicts, audit, MFA, expiry/revocation';
end $$;
rollback;
